CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS catalog; CREATE SCHEMA IF NOT EXISTS data; CREATE SCHEMA IF NOT EXISTS prediction; CREATE SCHEMA IF NOT EXISTS recommendation; CREATE SCHEMA IF NOT EXISTS audit;
CREATE TABLE IF NOT EXISTS catalog.student (student_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), external_student_id text NOT NULL UNIQUE, full_name text, email text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS catalog.course (course_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_code text NOT NULL, presentation text NOT NULL, name text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(course_code,presentation));
CREATE TABLE IF NOT EXISTS catalog.enrollment (enrollment_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid NOT NULL REFERENCES catalog.student(student_id), course_id uuid NOT NULL REFERENCES catalog.course(course_id), external_enrollment_id text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(student_id,course_id));
CREATE TABLE IF NOT EXISTS data.dataset (dataset_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dataset_key text NOT NULL UNIQUE, dataset_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS data.dataset_version (dataset_version_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dataset_id uuid NOT NULL REFERENCES data.dataset(dataset_id), version text NOT NULL, source_hash text, description text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(dataset_id,version));
CREATE TABLE IF NOT EXISTS data.temporal_observation (observation_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), enrollment_id uuid NOT NULL REFERENCES catalog.enrollment(enrollment_id) ON DELETE CASCADE, time_index integer NOT NULL, observation_date date, features jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(enrollment_id,time_index));
CREATE TABLE IF NOT EXISTS data.feature_snapshot (snapshot_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), enrollment_id uuid NOT NULL REFERENCES catalog.enrollment(enrollment_id) ON DELETE CASCADE, dataset_version_id uuid NOT NULL REFERENCES data.dataset_version(dataset_version_id), stage text NOT NULL, cutoff_value text, static_features jsonb NOT NULL DEFAULT '{}'::jsonb, aggregate_features jsonb NOT NULL DEFAULT '{}'::jsonb, temporal_summary jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(enrollment_id,dataset_version_id,stage));
CREATE TABLE IF NOT EXISTS prediction.model (model_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), model_key text NOT NULL UNIQUE, display_name text NOT NULL, model_type text, is_active boolean NOT NULL DEFAULT false, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS prediction.model_run (run_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), model_id uuid NOT NULL REFERENCES prediction.model(model_id), status text NOT NULL CHECK(status IN ('PENDING','RUNNING','COMPLETED','FAILED')), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS prediction.prediction (prediction_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), enrollment_id uuid NOT NULL REFERENCES catalog.enrollment(enrollment_id), run_id uuid NOT NULL REFERENCES prediction.model_run(run_id), snapshot_id uuid REFERENCES data.feature_snapshot(snapshot_id), stage text NOT NULL, risk_probability double precision NOT NULL CHECK(risk_probability BETWEEN 0 AND 1), predicted_risk boolean NOT NULL, threshold double precision NOT NULL CHECK(threshold BETWEEN 0 AND 1), uncertainty double precision, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(enrollment_id,run_id,stage));
CREATE TABLE IF NOT EXISTS recommendation.action (action_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action_key text NOT NULL UNIQUE, display_name text NOT NULL, description text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS recommendation.recommendation (recommendation_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), enrollment_id uuid NOT NULL REFERENCES catalog.enrollment(enrollment_id), prediction_id uuid REFERENCES prediction.prediction(prediction_id), status text NOT NULL DEFAULT 'PENDING', metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS recommendation.recommendation_item (recommendation_item_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recommendation_id uuid NOT NULL REFERENCES recommendation.recommendation(recommendation_id) ON DELETE CASCADE, action_id uuid NOT NULL REFERENCES recommendation.action(action_id), rank integer NOT NULL DEFAULT 1, rationale text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(recommendation_id,action_id));
CREATE TABLE IF NOT EXISTS audit.system_event (event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_type text NOT NULL, entity_type text, entity_id text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
